--
-- Table structure for table `article_reads`
--

DROP TABLE IF EXISTS `article_reads`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `article_reads` (
  `user_id` bigint NOT NULL,
  `article_id` bigint NOT NULL,
  `first_read_at` datetime(6) NOT NULL,
  `last_read_at` datetime(6) NOT NULL,
  `click_count` int unsigned NOT NULL DEFAULT '1',
  PRIMARY KEY (`user_id`,`article_id`),
  KEY `idx_article_reads_article_user` (`article_id`,`user_id`),
  KEY `idx_article_reads_user_recent` (`user_id`,`last_read_at` DESC),
  KEY `idx_article_reads_user_first_read` (`user_id`,`first_read_at` DESC),
  CONSTRAINT `fk_article_reads_article` FOREIGN KEY (`article_id`) REFERENCES `articles` (`article_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_article_reads_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `ck_article_reads_click_count` CHECK ((`click_count` >= 1)),
  CONSTRAINT `ck_article_reads_time_order` CHECK ((`first_read_at` <= `last_read_at`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='뉴스 카드 클릭 기준 기사 열람 기록';
/*!40101 SET character_set_client = @saved_cs_client */;

