--
-- Table structure for table `articles`
--

DROP TABLE IF EXISTS `articles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `articles` (
  `article_id` bigint NOT NULL AUTO_INCREMENT,
  `organization_id` bigint NOT NULL,
  `title` varchar(500) NOT NULL,
  `url` text NOT NULL,
  `url_hash` binary(32) NOT NULL,
  `published_at` datetime(6) NOT NULL,
  `source_category` varchar(100) DEFAULT NULL,
  `topic_code` varchar(32) DEFAULT NULL,
  `subtopic_code` varchar(64) DEFAULT NULL,
  `reporter` varchar(100) DEFAULT NULL,
  `content` mediumtext NOT NULL,
  `content_type` varchar(32) NOT NULL,
  `content_hash` binary(32) DEFAULT NULL,
  `summary` text,
  `summary_status` varchar(32) NOT NULL DEFAULT 'NOT_REQUESTED',
  `analysis_status` varchar(32) NOT NULL DEFAULT 'PROCESSING',
  `analysis_attempts` int NOT NULL DEFAULT '0',
  `analysis_failure_code` varchar(64) DEFAULT NULL,
  `node_id` char(36) DEFAULT NULL,
  `content_updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `summary_generated_at` datetime(6) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`article_id`),
  UNIQUE KEY `uk_articles_url_hash` (`url_hash`),
  UNIQUE KEY `uk_articles_node_id` (`node_id`),
  KEY `idx_articles_organization_published` (`organization_id`,`published_at` DESC),
  KEY `idx_articles_published_at` (`published_at` DESC),
  KEY `idx_articles_analysis_published` (`analysis_status`,`published_at` DESC),
  KEY `idx_articles_topic_subtopic_published` (`topic_code`,`subtopic_code`,`published_at` DESC),
  KEY `idx_articles_analysis_queue` (`analysis_status`,`analysis_attempts`,`article_id`),
  KEY `idx_articles_content_hash` (`content_hash`),
  CONSTRAINT `fk_articles_organization` FOREIGN KEY (`organization_id`) REFERENCES `news_organizations` (`organization_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=17335 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='기사 원본 및 서비스용 요약';
/*!40101 SET character_set_client = @saved_cs_client */;

