/*!40000 ALTER TABLE `articles` DISABLE KEYS */;
INSERT INTO `articles` VALUES (16342,271,'부캉이 굿즈 품절 행렬…시, 추가 생산·온라인 판매 확대','https://demo.starlightnews.local/articles/bbe7c070-1a61-4eff-836e-1cd460c8a029',_binary '�˿�\�\�F7奶�9��[ʰ�\��=�❸hO\r','2026-09-27 05:14:46.898341','DEMO','ECONOMY','ECONOMY_GENERAL',NULL,'가상시는 지난 20일 시청 광장에서 공식 마스코트 부캉이의 신규 굿즈 12종을 공개하고 현장 판매를 시작했다.\n판매 첫날 준비한 인형 3천 개가 오전 중 모두 팔렸고, 오후에는 구매 대기 줄이 광장 밖까지 이어졌다.\n굿즈가 조기 품절되자 온라인에서는 정가의 세 배가 넘는 가격에 되파는 사례가 잇따랐다.\n이에 가상시는 23일 인형 1만 개를 추가 생산하고 다음 달부터 공식 온라인몰 판매를 확대한다고 발표했다.\n김도윤 가상시 관광정책과장은 \"부캉이를 찾는 시민과 관광객이 예상보다 훨씬 많았다\"며 \"1인당 구매 수량을 제한해 되팔이를 막겠다\"고 말했다.\n지역 상인회는 부캉이 인기가 원도심 방문객 증가로 이어질 것으로 전망했다.','FULL_TEXT',_binary '%$\�\�1]��\�ѷ�\�\�@�\�k�B`-\�\�','가상시는 시청 광장에서 부캉이 신규 굿즈 12종을 공개하고 현장 판매를 시작했으며 인형 3천 개가 첫날 오전에 매진됐다. 온라인에서는 정가의 3배가 넘는 되팔기가 나오자 시는 인형 1만 개를 추가 생산하고 다음 달부터 온라인몰 판매를 확대할 전망이다.','COMPLETED','COMPLETED',0,NULL,'a975d4ec-b970-4f39-ac98-e4d3543fe964','2026-09-26 20:14:46.916801','2026-09-27 20:23:37.979664','2026-09-26 20:14:46.916801','2026-09-27 11:23:37.981737'),(16343,28,'은행 문만 열면 뭐하나…현금이 없는데','https://demo.starlightnews.local/articles/7007ef48-5411-4fcc-9cf7-383807b74776',_binary '�\n5\�G�<{\���ul �[\� E���W�\�#ȋ','2026-09-27 05:18:43.131087','DEMO','INTERNATIONAL','MIDDLE_EAST_AFRICA',NULL,'이스라엘과 팔레스타인 무장정파 하마스간 휴전으로 가자지구의 은행들이 다시 문을 열었지만 현금 부족으로 정상적인 영업이 이뤄지지 않고 있다.\n31일(현지시간) 로이터통신에 따르면 휴전 발효 6일 만인 지난 16일부터 가자지구의 은행 지점들이 업무를 재개했다. 그러나 돈을 뽑으려 은행 앞에 길게 늘어섰던 주민들은 이내 실망과 함께 발걸음을 돌려야만 했다. 팔레스타인은행 지점에 들렀던 와엘 아부 파레즈(61)는 \"은행에 돈이 없다\"며 \"서류로 하는 거래만 하고 나가야 한다\"고 말했다.\n지난 2년여간 전쟁이 이어지면서 이스라엘에서 가자지구로 현금 공급이 중단됐다. 가자지구에서는 이스라엘 화폐인 셰켈(NIS)이 사용되는데, 휴전 합의 이후에도 발표된 지폐 반입 등의 계획은 없는 상황이다. 현금이 귀해지다 보니 지폐를 수선하는 일로 돈을 버는 사람들도 생겼다.\n가자지구의 상인 사미르 남루티(53)는 오래 유통돼 알아볼 수 없는 정도가 된 지폐에도 익숙해졌다고 한다. 남루티는 \"지폐의 일련번호가 중요하다\"며 \"일련번호만 있으면 돈이다\"라고 말했다\n정지연 기자','FULL_TEXT',_binary 'ҩp�=A殦\�\�K\�Պ��/�,#D��\nvX}\�N\�',NULL,'NOT_REQUESTED','COMPLETED',0,NULL,'f92cfe16-a6a5-4c95-8d0c-9d1637377bf6','2026-09-26 20:18:43.134289',NULL,'2026-09-26 20:18:43.134289','2026-09-26 20:19:00.317450'),(16344,28,'코레일·부산교통공사, 부산역서 무인 배송로봇 공동 실증 시작','https://demo.starlightnews.local/articles/ced37cb1-ce36-4394-9363-22413edabebc',_binary '\�V�	9a\�\�2���\�c\�G�\�.�u\�\�\�]I�(','2026-09-27 05:26:00.689952','DEMO','IT_SCIENCE','SCIENCE',NULL,'한국철도공사(코레일)와 부산교통공사는 26일부터 부산역 일대에서 무인 배송로봇 공동 실증을 시작했다고 밝혔다. 두 기관은 로봇을 이용해 역사 내 편의점과 물류보관소 사이에서 소형 화물을 운송하고, 이동 경로와 장애물 대응 성능을 점검할 계획이다.\n이번 실증에는 로봇 제작사인 한빛로보틱스가 장비를 공급했으며, 동남교통연구원은 주행 데이터를 분석한다. 부산 동구청은 보행자 안전과 관련한 현장 점검에 참여한다.\n코레일은 실증 결과를 바탕으로 향후 다른 주요 역사로 서비스를 확대할 수 있다고 설명했다. 부산교통공사 관계자는 “혼잡 시간대의 안전성을 충분히 확인한 뒤 실제 도입 여부를 결정할 것”이라고 말했다.','FULL_TEXT',_binary '*C�L\�A=�\�!͠S\�9$\r�r�3\�Ӓt�#5\��',NULL,'NOT_REQUESTED','COMPLETED',0,NULL,'c804e9a5-29d5-40b2-9c5f-8ebd213096f5','2026-09-26 20:26:00.694127',NULL,'2026-09-26 20:26:00.694127','2026-09-26 20:26:17.206944'),(16345,8,'‘DMZ 지뢰 폭발’ 5일 만에…군·유엔사, 현장조사 준비','https://www.hani.co.kr/arti/politics/politics_general/1279532.html',_binary '̜jl�[l1^�\�:<\��о\�\�[���K}�\�\�','2026-09-26 21:05:00.000000','general','POLITICS','NORTH_KOREA',NULL,'군과 유엔군사령부가 26일 비무장지대(DMZ)에 병력을 투입해 최근 서부전선에서 발생한 지뢰 추정 폭발 사고 현장조사를 위한 준비 활동을 벌였다. 지난 21일 사고가 발생한 지 5일 만이다.\n합동참모본부(합참)는 이날 “군과 유엔사는 오늘 합동으로 DMZ 내 지뢰 추정 폭발 상황 관련 현장조사를 위한 기동로 확보 및 작전환경 조사를 했다”고 밝혔다. 준비 활동에 투입된 인원은 합참 차장이 이끄는 합참 합동 현장조사 태스크포스(TF) 인원과 유엔... [612 chars]','TRUNCATED_TEXT',_binary '�\'\�D��i)��U�y\�ߘ\��<��r�\�',NULL,'NOT_REQUESTED','COMPLETED',0,NULL,'a5b8082c-5a8f-4a0f-83ce-30b6c3c0d7bc','2026-09-27 00:10:21.449982',NULL,'2026-09-27 00:10:21.449982','2026-09-27 00:20:14.330793'),(16346,8,'중 관계에 ‘존중·공정·대등’ 추가…중국, 정상회담 성과 발표','https://www.hani.co.kr/arti/international/international_general/1279531.html',_binary '��\�F�\�Uђ<W\�\�%�0�\�,\�s`\�*�\�\�','2026-09-26 21:01:00.000000','general','INTERNATIONAL','CHINA',NULL,'중국이 미국 워싱턴에서 열린 미중 정상회담을 통해 양국이 ‘건설적 전략 안정 관계’ 구축 입장을 재확인하고 이란전쟁, 무역, 마약 등 8개 의제에 대해 합의를 이뤘다고 발표했다.\n중국 신화통신은 26일 발표문에서 시진핑 국가주석의 23∼25일 미국 국빈 방문 기간에 양국 정상이 “중·미 건설적 전략 안정 관