--
-- Table structure for table `recommendation_events`
--

DROP TABLE IF EXISTS `recommendation_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `recommendation_events` (
  `event_id` char(36) NOT NULL,
  `title` varchar(500) NOT NULL,
  `summary` text,
  `summary_status` varchar(32) NOT NULL DEFAULT 'NOT_REQUESTED',
  `topic_code` varchar(32) NOT NULL,
  `event_updated_at` datetime(6) DEFAULT NULL,
  `summary_generated_at` datetime(6) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`event_id`),
  KEY `idx_recommendation_events_summary_status` (`summary_status`),
  KEY `idx_recommendation_events_topic_code` (`topic_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='추천 Event 공통 표시 정보 및 요약 캐시';
/*!40101 SET character_set_client = @saved_cs_client */;

