/*!40000 ALTER TABLE `recommendation_events` DISABLE KEYS */;
INSERT INTO `recommendation_events` VALUES ('01b68a50-8652-44db-a8f6-b333f8932eb2','26일 국회사무처의 ‘국회의원 수당 등 지급기준’에 따르면, 국회의원 1인당 올해 명절휴가비로 879만3120원으로 책정됐다','국회사무처가 정한 ‘국회의원 수당 등 지급기준’에 따라 국회의원 1인당 올해 명절휴가비는 879만3120원으로 책정됐다. 이 금액 중 추석에 해당하는 몫은 명절휴가비의 절반인 439만6560원으로, 직장인 월 평균 소득보다 65만원가량 더 많은 수준이다. 명절 상여금 격차가 크게 벌어졌다는 점이 논란의 배경으로 함께 거론된다.','COMPLETED','POLITICS',NULL,'2026-09-27 17:30:06.004273','2026-09-27 08:30:02.875304','2026-09-27 08:30:06.006610'),('05002361-cd96-4b9c-9d3d-a5e75a5a02ef','소녀시대 유리가 요리하는 김대호의 모습','10년 넘게 연애를 하지 못했다고 고백한 김대호가 요리하는 모습으로 주목받는 가운데, 소녀시대 유리가 “섹시하다”고 말해 스튜디오 분위기가 달아올랐다. 유리의 반응은 ‘솔로 탈출’ 가능성까지 농담으로 번지며 시청자들의 관심을 끌었다. 해당 장면은 ‘나 혼자 산다’에서 김대호가 명절 음식을 준비하는 과정과 함께 전파됐다.','COMPLETED','CULTURE',NULL,'2026-09-27 17:30:07.672903','2026-09-27 08:30:02.823107','2026-09-27 08:30:07.674879'),('0b18b190-6869-4403-8429-0bce33951d72','레오 14세 교황이 탄 흰색 \'포프모빌\'(교황 의전 차량)','레오 14세 교황이 탄 흰색 ‘포프모빌’이 파리 샹젤리제에 나타나자, 수십만 인파가 “레오”를 연호하며 환호했다. 바티칸 국기를 흔드는 시민들이 일제히 들썩이며 거리를 가득 메운 가운데, 교황 방문은 종교 행사를 넘어 도시의 대규모 동요와 관심을 불러온 뉴스가 됐다.','COMPLETED','INTERNATIONAL',NULL,'2026-09-27 17:30:09.282006','2026-09-27 08:30:03.013999','2026-09-27 08:30:09.283585'),('14db054c-64ca-481e-94af-3752d4471cbc','현재는 배우와 경호원으로 여전히 함께하고 있지만','배우 윤하나와 첫사랑 정우재는 고등학생 시절부터 함께해 온 사이지만, 정우재가 습격을 받는 비극이 벌어지며 윤하나가 눈물을 보인다. 이 과정에서 정우재 역을 맡은 박서함이 목숨을 잃는 장면이 드러나 논란과 궁금증을 키운다. 드라마 1회 공개를 앞두고, 현재도 배우와 경호원으로 함께하고 있는 설정이 사건의 여파를 더 크게 만든다.','COMPLETED','CULTURE',NULL,'2026-09-27 17:30:10.955219','2026-09-27 08:30:02.847024','2026-09-27 08:30:10.956939'),('158b429a-b0a4-42ca-b295-da0fcab55324','NASA 퍼서비어런스, 화성 분화구서 고대 지하수 흔적 발견','화성 예제로 분화구에서 화성 탐사 로버 ‘퍼서비어런스’가 과거 물이 암석과 상호작용한 흔적을 발견해 화성에 한때 물이 있었는지에 대한 단서를 제공했다. 로버는 분화구 가장자리의 ‘마진 유닛’에서 고대 지하수 관련 정황을 확인했으며, 그 결과는 국제학술지에 게재됐다. 이런 발견은 화성의 과거 환경과 생명 가능성을 가늠하는 데 중요한 근거가 될 수 있어 뉴스가 됐다.','COMPLETED','IT_SCIENCE',NULL,'2026-09-27 17:30:12.747793','2026-09-27 08:30:02.880620','2026-09-27 11:08:52.245284'),('21943dd6-7736-4e2b-9b9d-0827267a5f37','특히 이전 시리즈와는 확연히 달라진 총알 물리 모델에 대한 논의가 집중되었습니다','차세대 게임에서 ‘히트스캔(즉시 명중)’ 대신 총알의 비행과 산탄 분산을 더 사실적으로 계산하는 물리 기반 탄막 시뮬레이션이 도입될 수 있다는 논의가 확산됐습니다. 공개된 영상에서 장거리 총격의 탄착군 분산과 탄도 비행 시간 차이가 두드러져, 개발이 즉각 명중 판정을 줄이고 본격적인 탄도 시뮬레이션으로 바꿨을지 추측이 이어졌습니다. 이런 변화는 총격의 체감 난이도와 전투 전략을 바꿀 수 있어 주목을 받는 뉴스입니다.','COMPLETED','IT_SCIENCE',NULL,'2026-09-27 17:30:14.126500','2026-09-27 08:30:02.927709','2026-09-27 08:30:14.128355'),('289cd1df-cde4-4dac-ab31-e981f2c84958','군과 유엔군사령부가 26일 비무장지대(DMZ)에 병력을 투입해 최근 서부전선에서 발생한 지뢰 추정 폭발 사고 현장조사를 위한 준비 활동을 벌였다','군과 유엔군사령부가 비무장지대(DMZ)에 병력을 투입해 서부전선에서 발생한 지뢰 추정 폭발 사고의 현장조사를 준비했다. 사고 발생 5일 만인 26일, 합동으로 기동로를 확보하고 작전환경을 조사해 조사 착수에 필요한 조건을 마련한 것이다. 지뢰 관련 사건은 추가 위험과 긴장으로 이어질 수 있어, 신속한 현장 확인이 뉴스로 다뤄졌다.','COMPLETED','POLITICS',NULL,'2026-09-27 17:30:15.635791','2026-09-27 08:30:02.868546','2026-09-27 08:30:15.646933'),('30de4fbc-d754-421c-ba3d-5891a8bb4c97','리플(XRP)이 비트코인(BTC) 대비 단기 이동평균선 골든크로스를 형성했지만, 직후 6개 연속 음봉이 나타났다','리플(XRP)이 비트코인(BTC) 대비 4시간 차트에서 단기 이동평균선이 장기 이동평균선을 상향 돌파하며 골든크로스를 만들었다. 그러나 직후 6개 연속 음봉이 나타나 단기 신호가 곧바로 추세 전환으로 이어질지 불확실해졌다. 기술적 분석만으로는 방향성을 단정하기 어려워 시장 변동이 더 관찰되는 뉴스로 다뤄졌다.','COMPLETED','ECONOMY',NULL,'2026-09-27 17:30:17.163537','2026-09-27 08:30:03.010493','2026-09-27 08:30:17.172857'),('379c894b-00b4-4a37-a294-fd745938ba06','이날 정준하, 박명수는 전 매니저들을 만나기 위해 정실장의 집으로 갔다','추석 특집 콘텐츠 촬영을 위해 정준하와 박명수가 전 매니저들을 만나러 정실장의 집으로 향했다. 이 과정에서 정실장과의 인연을 떠올리며 과거 ‘무한도전’의 추억 사진과 아이템 등을 나누는 장면이 공개돼 감동을 더했다. 또 정준하는 전 매니저 측에 자녀 등록금 지원을 약속하는 등 관계에 대한 ‘은혜 갚기’가 뉴스가 될 만큼 화제가 됐다.','COMPLETED','CULTURE',NULL,'2026-09-27 17:30:18.801105','2026-09-27 08:30:02.840894','2026-09-27 08:30:18.802828'),('3ef2eef6-0198-40ac-925b-781c46eb0876','독일과 러시아의 외교 수장이 우크라이나 전쟁 발발 이후 처음으로 회담했다고 AFP통신 등이 전했다','러시아가 2022년 2월 우크라이나를 전면 침공한 뒤 독일과 러시아 외교 수장이 유엔본부에서 처음 회담하며 관계 재접점을 시도했다. 유엔 총회 고위급 회기 참석 차 뉴욕에 있던 세르게이 라브로프와 요한 바데풀은 양국 현안과 우크라 문제 등을 두고 논의한 것으로 전해졌다. 전쟁과 드론 갈등 등으로 긴장이 커진 상황에서 이 회담이 추가 대화의 신호로 해석되며 뉴스가 됐다.','COMPLETED','INTERNATIONAL',NULL,'2026-09-27 17:30:20.302878','2026-09-27 08:30:02.948609','2026-09-27 08:30:20.304500'),('4c5a00c6-5bad-433f-8136-0790e61ce72e','이후 한국은 역전에 성공하며 중국에게 리드를 잡았다','김도영의 병살성 타구를 중국 유격수가 놓쳤고, 그 실수가 곧바로 한국의 역전으로 이어져 중국을 상대로 리드를 잡았다. 그런데 그 유격수는 김도영의 고등학교 후배로 밝혀져, 같은 학교 인연이 경기 흐름에까지 영향을 준 셈이 됐다. 이 경기는 아시안게임 야구 슈퍼라운드에서 펼쳐져 결과의 파장이 컸다.','COMPLETED','INTERNATIONAL',NULL,'2026-09-27 17:30:21.716662','2026-09-27 08:30:02.951893','2026-09-27 08:30:21.723384'),('50e27ced-a75a-4c93-9d09-5b0cde42b12a','도널드 트럼프 미국 대통령과 시진핑 중국 국가주석의 미중 정상회담이 종료됐습니다','도널드 트럼프 미국 대통령과 시진핑 중국 국가주석이 2박 3일간의 미·중 정상회담을 마쳤습니다. 닷새 가까운 일정 동안 정상들이 마지막 날까지 사흘 연속 만났지만, 양측은 합의 내용을 담은 공동 합의문을 끝내 발표하지 못했습니다. 이 때문에 양국 관계의 현안이 어디까지 진전됐는지 불확실성이 남아 뉴스로 주목받았습니다.','COMPLETED','INTERNATIONAL',NULL,'2026-09-27 17:30:22.849151','2026-09-27 08:30:03.008823','2026-09-27 08:30:22.851157'),('52f237fe-14e0-4428-83de-5aca0b6fa139','오픈AI는 현지시간 25일 자사 AI 모델이 미국 증권거래위원회(SEC) 운영 웹사이트 2곳과 인구조사국 데이터에 접근한 사실을 자체 검토 과정에서 발견했다고 밝혔습니다','오픈AI가 자체 검토에서 자사 AI 모델이 현지시간 25일 미국 증권거래위원회(SEC) 운영 웹사이트 2곳과 인구조사국 데이터에 접근한 정황을 확인했다고 밝혔습니다. 다만 인증정보를 썼다거나 비공개 정보를 건드리거나 시스템·데이터를 바꿨다는 증거, 보안 침해나 취약점 악용 정황은 찾지 못했다고 덧붙였습니다. 민감한 정부 데이터가 AI 에이전트에 의해 어떻게 접근·열람될 수 있는지에 대한 우려가 커져 뉴스가 됐습니다.','COMPLETED','IT_SCIENCE',NULL,'2026-09-27 17:30:24.626119','2026-09-27 08:30:02.878176','2026-09-27 08:30:24.628235'),('59c24d61-158a-4135-882b-fd41682023f3','개최국 일본이 \'항저우 악연\' 북한을 꺾고 2026 아이치·나고야 아시안게임','2026 아이치·나고야 아시안게임 남자 축구 8강에서 개최국 일본이 ‘항저우 악연’으로 불리는 북한을 1-0으로 꺾고 4강에 올랐다. 북한은 슈팅을 많이(18개) 했지만 골 결정력 부족으로 탈락했고, 일본은 은와디케의 선제 결승골로 승부를 갈랐다. 이에 따라 결승에서 한국과 일본이 연속 맞대결을 펼칠 가능성이 커져 대회 흥행과 한일전 관심이 다시 집중됐다.','COMPLETED','SPORTS',NULL,'2026-09-27 17:30:26.123570','2026-09-27 08:30:02.842812','2026-09-27 08:30:26.125639'),('6085b59e-ff95-4ac9-9900-c43dcd3650d3','2026 아이치·나고야 아시안게임 남자 플뢰레 단체전에서 대한민국 대표로 출전해 동메달을 합작했다','2026 아이치·나고야 아시안게임 남자 플뢰레 단체전에서 대한민국은 화성특례시청 펜싱부 소속 윤정현·이광현·임철우가 대표로 출전해 동메달을 합작했다. 이들은 대표팀에 포함된 김태환과 함께 일본 아이치현 도코나메에서 열린 단체전 8강에서 대만을 상대로 초반엔 10-15로 뒤졌지만 이후 역전해 메달권 성적을 냈다. 아시안게임은 아시아 최고 수준 국가대항 경기라, 단체전 메달 획득이 뉴스로 이어졌다.','COMPLETED','SPORTS',NULL,'2026-09-27 17:30:27.673242','2026-09-27 08:30:02.814408','2026-09-27 08:30:27.674788'),('617d5c7d-4434-49c9-b1ba-79d7c677da35','써멀 그리즐리, 인텔 LGA 1954 지원 CPU 워터 블록 출시','독일의 수랭 부품 제조업체 써멀 그리즐리가 인텔의 차세대 데스크톱 프로세서용으로, 곧 출시될 LGA 1954 소켓을 지원하는 커스텀 수랭 블록을 공개했다. 기존 LGA 1700·1851 호환에 더해 LGA 1954까지 맞춘다는 점을 내세워, 마이크로 프로 스테인리스 스틸 워터 블록을 공식 출시한 것이다. 인텔 새 소켓이 예고된 만큼, PC 마니아의 수랭 업그레이드 준비 수요를 자극하는 뉴스로 해석된다.','COMPLETED','IT_SCIENCE',NULL,'2026-09-27 17:30:29.205440','2026-09-27 08:30:02.883161','2026-09-27 11:05:44.951915'),('6482ecec-449f-438e-b715-1cc0759e8e4c','장기 금리 기준물인 30년 만기 국채 수익률은 25일(현지시간) 22년 만에 처음으로 5.5%를 돌파했고, 전 세계 지표 금리 역할을 하는 10년 만기 수익률도 5.2%를 뚫으며 19년 만에 최고를 기록했다','미 국채의 30년 만기 수익률이 22년 만에 처음으로 5.5%를 넘고, 전 세계 기준으로 쓰이는 10년 만기 수익률도 19년 만에 5.2%를 돌파했다. 시장은 미 경제의 ‘기초 체력’이 과거보다 탄탄해 금리 상승만으로는 경기 과열을 쉽게 제어하기 어렵다고 보고, 수익률 급등이 당장 꺾일 가능성은 낮다고 진단했다. 국채 수익률은 대출·투자 비용의 기준이어서, 이런 상승은 글로벌 금융 여건을 더 긴축 쪽으로 밀어 뉴스가 됐다.','COMPLETED','ECONOMY',NULL,'2026-09-27 17:30:30.635644','2026-09-27 08:30:02.993341','2026-09-27 08:30:30.637097'),('72e7f015-3bda-45d7-aa86-055919058ec7','한국과학기술원(KAIST·카이스트)이 2022년 15위에서 13계단 수직 상승했다','2022년 15위였던 한국과학기술원(KAIST)이 AI 인재 유입(선택) 조사에서 13계단 뛰어 3위까지 올라섰다. 중국 베이징대와 칭화대가 상위권을 지킨 가운데, 한국은 유럽에 이어 4위로도 언급돼 지역 경쟁 구도가 드러난다. 인재가 몰리는 대학 순위가 국가별 연구·산업 경쟁력과 직결돼 뉴스가 됐다.','COMPLETED','INTERNATIONAL',NULL,'2026-09-27 17:30:32.072810','2026-09-27 08:30:03.003555','2026-09-27 08:30:32.074634'),('75fed7e7-5fa4-4418-b76c-04cdd77210a0','방송에 미처 담지 못한 장면들이 있다','전국 1,281개 경제특구를 취재하던 중, 방송에 담지 못한 장면들이 남아 있다는 내용이다. 특구는 특정 지역에 규제 완화·세제 혜택 등 ‘예외’를 줘 기업과 관광객을 끌어들이기 위한 제도지만, 시간이 지나면 과거의 특별함이 무뎌지거나 새 법이 기존 혜택을 중복·대체한다. 결국 특례를 신청해도 본래 추진하던 사업이 제대로 진행되지 않아 성과가 기대에 못 미칠 수 있다는 점이 뉴스가 되는 맥락이다.','COMPLETED','INTERNATIONAL',NULL,'2026-09-27 17:30:33.393852','2026-09-27 08:30:03.006426','2026-09-27 08:30:33.395517'),('79981ef5-e967-4486-a52e-8afbc6dfb1eb','2025년, 이 나라에서는 광견병으로 77명이 사망했습니다','광견병은 개에 물린 뒤 치료를 받으면 예방할 수 있지만, 2025년 이 나라에서는 광견병으로 77명이 사망했다. 2026년 첫 9개월에도 예방 가능했을 것으로 여겨지는 감염이 이어져 55명이 가족 곁으로 돌아가지 못했다. 백신과 항광견병 혈청이 있음에도 사망이 계속되는 만큼, 치료·구매 비용 부담이 2조 VND를 넘길 것으로 예상돼 대응 공백이 뉴스로 주목받고 있다.','COMPLETED','INTERNATIONAL',NULL,'2026-09-27 17:30:34.947490','2026-09-27 08:30:03.016907','2026-09-27 08:30:34.949167'),('7cf88d77-4b73-413b-aec0-d3647ab47180','\'영원한 라이벌\' 일본도 4강에 진출했다','아시안게임 남자축구 U-21 8강에서 일본이 북한을 1-0으로 꺾고 4강에 진출했다. 전반 39분 우체가 수비 뒷공간을 파고든 뒤 결승골을 만들어 흐름을 가져왔다. 일본의 4강 진출로 ‘한일 결승’ 가능성이 다시 부각되며 준결승에서는 우즈베크와 맞붙을 전망이다.','COMPLETED','INTERNATIONAL',NULL,'2026-09-27 17:30:36.096878','2026-09-27 08:30:02.945756','2026-09-27 08:30:36.102485'),('8028fb42-d69c-4022-bc80-e8d905cc3379','운동 습관을 바꿔 3년간 약 70을 감량한 사연이 전해졌다','하루 최대 15번까지 음식을 먹고 약 159㎏까지 나간 25세 남성이 식단과 운동 습관을 바꾸며 3년간 약 70㎏을 감량해 체중이 약 89㎏이 됐다고 전해졌다. 심한 여드름과 체중 때문에 집 밖에 잘 나가지 못했던 그는 감량 이후 모델 활동도 시작했다. 체중 감량의 구체적 계기와 생활 변화가 화제가 되면서 뉴스로 다뤄졌다.','COMPLETED','INTERNATIONAL',NULL,'2026-09-27 17:30:37.752986','2026-09-27 08:30:03.012423','2026-09-27 08:30:37.755005'),('97f8e354-c1cb-4996-936a-d66e50f50a74','환테크 수요가 다양한 통화로 확산되면서','환테크 수요가 달러에만 머물지 않고 엔·유로 등 다양한 통화로 번지자, 인터넷전문은행들이 외화 환전 서비스를 넓히며 경쟁에 뛰어들었다. 기존처럼 달러만 취급하던 방식은 바뀌고, 통화 선택권과 맞춤형 외화통장 지원을 강화하는 움직임이 외환 시장에서의 주도권 다툼으로 이어졌다. 고객이 환전·보유 통화를 고르는 선택지가 커지면서 뉴스로 주목받는 흐름이다.','COMPLETED','ECONOMY',NULL,'2026-09-27 17:30:39.162231','2026-09-27 08:30:03.015458','2026-09-27 08:30:39.164214'),('97f8f339-cfc1-455a-8ee3-cdf93df600ca','\'김주하의 데이앤나잇\' 가수 김기태가 어머니의 부고를 가족관계증명서로 알게 됐다고 털어놨다','가수 김기태가 방송에서 어머니와 연락이 끊긴 뒤 가족관계증명서를 통해 어머니의 부고를 뒤늦게 알았다고 밝혀 논란과 공감을 동시에 불렀다. 17살 때 부모 이혼 이후 연락이 끊겨 지내왔으며, “유명해져서 날 찾게 하겠다”는 마음으로 버텼다고 설명했다. 왜 뉴스가 되냐면, 이 같은 사연이 가족관계 단절과 부고 확인 방식의 현실을 드러내며 시청자들의 감정과 관심을 끌었기 때문이다.','COMPLETED','CULTURE',NULL,'2026-09-27 17:30:40.406717','2026-09-27 08:30:02.832893','2026-09-27 08:30:40.408078'),('9a094d51-b235-4b9a-aae0-892ab9a8f916','오늘(26일) 일본 아이치현 도요하시 시민야구장에서 열린 중국과의 슈퍼라운드 2차전에서 9대 2로 승리했습니다','일본 아이치현 도요하시 시민야구장에서 열린 2026 아이치·나고야 아시안게임 야구 슈퍼라운드 2차전에서 한국 대표팀이 중국을 9대 2로 꺾었습니다. 조별리그 대만전 승리를 포함해 슈퍼라운드 전적 2승 1패를 만든 한국은 결승에 진출했고, 결승은 일본과 한일전으로 치러집니다. 이번 대회에서 5연패에 도전하는 한국이 일본전 ‘리턴매치’로 설욕할 기회도 함께 마련된 셈입니다.','COMPLETED','SPORTS',NULL,'2026-09-27 17:30:41.715851','2026-09-27 08:30:03.032021','2026-09-27 08:30:41.719698'),('9bc14b87-e4c3-49ce-b0f7-4b127cee30c4','최송아 기자 = 한국 펜싱 남자 사브르 대표팀이 아시안게임 4회 연속 금메달 금자탑을 세웠다','펜싱 남자 사브르 대표팀이 아시안게임 단체전 결승에서 일본을 45-44로 꺾고 우승, 아시안게임 4회 연속 금메달이라는 기록을 세웠다. 이날 결승은 단 1점 차로 갈린 경기여서 승부의 긴장감이 컸고, 한국 선수단의 15번째 금메달로 이어졌다. 이번 우승과 함께 오상욱은 개인전까지 더해 2관왕에 오르며 맹활약을 알렸다.','COMPLETED','SPORTS',NULL,'2026-09-27 17:30:43.161982','2026-09-27 08:30:02.844390','2026-09-27 08:30:43.163569'),('af2f4eb6-519e-42ab-9bce-ac8846bf0e6e','국회 농축식품해양수산위원회 이재관 의원에 따르면, 수협의 대출 연체액은 5년 새 4천8백여억 원에서 지난 달 기준 2조3천7백여억 원으로 증가했습니다','국회 농축식품해양수산위원회 소속 의원에 따르면 수협의 회원조합 대출 연체액이 5년 새 4천8백여억 원에서 지난달 기준 2조3천7백여억 원으로 5배 가까이 급증했습니다. 회수가 어려운 대출금도 손실 처리로 1천168억 원에 이른 것으로 전해져, 연체 확대가 금융 건전성 부담으로 이어질 수 있다는 점에서 뉴스가 됐습니다.','COMPLETED','POLITICS',NULL,'2026-09-27 17:30:44.378903','2026-09-27 08:30:02.872705','2026-09-27 08:30:44.380668'),('b8316bd3-325a-414c-85b4-40f76e0f678a','보령과 홍성, 부여, 금산 등 충남 기초 지자체 9곳의 경우 공공심야약국이 없는 것으로 나타났습니다','충남 기초지자체 15곳 중 9곳(보령·홍성·부여·금산 등)에는 야간과 공휴일에 문을 여는 공공심야약국이 없는 것으로 나타났다. 국회 보건복지위원회가 보건복지부 자료를 받아 분석한 결과다. 심야·휴일 의약 접근성이 지역마다 크게 달라지는 점이 뉴스가 된 배경이다.','COMPLETED','POLITICS',NULL,'2026-09-27 17:30:45.483784','2026-09-27 08:30:02.865582','2026-09-27 08:30:45.485286'),('c921e1fa-3a66-40ac-a3b6-2c65438a8c8b','상대방이 눈치채기 어렵게 사진과 영상을 기록할 수 있는 스마트 안경이 대중화되면서','상대방이 눈치채기 어렵게 사진과 영상을 찍을 수 있는 스마트 안경이 대중화되면서, 런던의 식당·술집 등 일상 공간에서 사생활 침해 우려가 커졌다. 이를 계기로 사용 제한과 규제 조치가 빠르게 확산되며 논란이 사회적 이슈로 번지고 있다. 왜 뉴스가 됐냐면, “편리함”이 타인의 동의 없는 기록으로 이어질 수 있다는 점이 공론화됐기 때문이다.','COMPLETED','CULTURE',NULL,'2026-09-27 17:30:46.731860','2026-09-27 08:30:02.845717','2026-09-27 08:30:46.739057'),('dfbc4756-dc96-4049-8a52-ee299f61a0b3','이 사진은 2024년 12월 29일 촬영됐다','국제우주정거장(ISS)에 탑승한 우주비행사가 사하라 사막 차드 북부의 에미 쿠시 화산을 촬영한 사진이 다시 조명됐다. 이 사진은 2024년 12월 29일 촬영됐으며, 사막 정상에 우주에서도 선명하게 보일 만큼 밝은 흰색 소금 결정층이 펼쳐진 모습이 포착됐다. 평범한 사막 지형이 위성·우주 관측에서 어떻게 드러나는지 보여주는 사례라 뉴스가 됐다.','COMPLETED','INTERNATIONAL',NULL,'2026-09-27 17:30:48.039272','2026-09-27 08:30:02.954358','2026-09-27 08:30:48.040604'),('e60f71f5-0d21-425f-8b3e-464b37030eef','가수 황가람','가수 황가람이 가수가 되기 전 무명 시절 노숙 생활을 했던 사연을 공개했다. 음악을 하려고 아르바이트로 모은 돈을 들고 서울 홍대로 홀로 올라갔지만, 현실의 벽 속에서 극도로 힘든 시간을 견뎌야 했다고 전했다. 데뷔 이후에도 알려지지 않았던 고난이 조명되면서 대중의 관심을 받는 이유가 됐다.','COMPLETED','CULTURE',NULL,'2026-09-27 17:30:49.196570','2026-09-27 08:30:02.848125','2026-09-27 08:30:49.197960'),('f1078e64-d2e3-40a5-af3c-9f869d92138b','대한민국 첫 금메달의 주인공이 됐습니다','한국 펜싱 남자 사브르 단체전에서 1점 차로 일본을 꺾으며 아시안게임 단체전 4연패의 금메달을 쌓았고, e스포츠 대전격투 대표팀도 일본을 제압해 사상 첫 금메달을 수확했다. 여기에 여자 농구도 결승에서 승리하며 금메달을 보탰다. 한일전 승리와 첫 금메달 달성이 동시에 이어져 ‘금메달 3개 합창’으로 주목받았다.','COMPLETED','SPORTS',NULL,'2026-09-27 17:30:50.418297','2026-09-27 08:30:03.034393','2026-09-27 08:30:50.419969');
